actions.script:
def _valid = ['activity','topcust']
def _clean = ((context.order ?: '').toString().split(',') as List).findAll { _valid.contains(it) }
ec.user.setPreference('CONTACT_DASH_ORDER', _clean.join(','))
// widget width presets ('half'/'third'; 'full' is the default and not stored) — validated + bounded
if (context.sizes != null) {
    if (context.sizes == '__full__') {   // every widget full — a real saved state (vs empty = use default)
        ec.user.setPreference('CONTACT_DASH_SIZE', '__full__')
    } else {
        def _sz = ((context.sizes ?: '').toString().split(',') as List)
                .collect { it.split(':') as List }
                .findAll { it.size()==2 && _valid.contains(it[0]) && ['half','third'].contains(it[1]) }
                .collect { it[0]+':'+it[1] }
        ec.user.setPreference('CONTACT_DASH_SIZE', _sz.join(','))
    }
}
ec.web.sendJsonResponse([saved:true, order:_clean.join(',')])

import org.moqui.entity.EntityCondition
def ef = ec.entity

// ===== ZE-DASH date-range filter =====
// NOTE: contacts have no reliable "created/became-a-customer" date in the data (party/party_role
// carry only last_updated_stamp), so a date filter over the directory counts would be a no-op OR a
// fabrication. The honest time dimension for a Contacts view is customer *transaction activity*:
// finalised sales invoices (invoiceDate, org-scoped) — same "finalised sale" basis as SalesDashboard.
// The range drives ONLY the Customer Activity chart, Top Customers, and the "active in range" stat.
// The Customers/Suppliers directory totals above stay "current" (MARUTHI-safe).
def _sdf = new java.text.SimpleDateFormat("yyyy-MM-dd")
_sdf.setTimeZone(ec.user.timeZone)
def _now = ec.user.nowTimestamp
def _todayStr = _sdf.format(_now)
def _today = java.time.LocalDate.parse(_todayStr)
def _weekStart = _today.minusDays(_today.dayOfWeek.value % 7)
def _monthStart = _today.withDayOfMonth(1)
def _yearStart = _today.withDayOfYear(1)
def _currentYear = _today.year
growthYear = growthYear?.toString() == (_currentYear - 1).toString() ? _currentYear - 1 : _currentYear
def _growthParam = '&growthYear=' + growthYear
dashDate = (dashDate ?: '').toString().trim()
dashDateTo = (dashDateTo ?: '').toString().trim()
dateError = ''
if (!dashDate && dashDateTo) dashDate = dashDateTo
if (!dashDate && dateMode != 'all' && dateMode != 'custom') {
    dashDate = _todayStr; dashDateTo = _todayStr; dateMode = 'today'
}
dayStart = null; dayEndExcl = null
if (dashDate) {
    try {
        def _first = java.time.LocalDate.parse(dashDate)
        def _last = java.time.LocalDate.parse(dashDateTo ?: dashDate)
        if (_last.isBefore(_first)) { def _swap = _first; _first = _last; _last = _swap }
        if (_first.year < 1900 || _last.year > 9998) throw new IllegalArgumentException('Date outside supported range')
        dashDate = _first.toString(); dashDateTo = _last.toString()
        def zone = ec.user.timeZone.toZoneId()
        dayStart = java.sql.Timestamp.from(_first.atStartOfDay(zone).toInstant())
        dayEndExcl = java.sql.Timestamp.from(_last.plusDays(1).atStartOfDay(zone).toInstant())
    } catch (IllegalArgumentException | java.time.DateTimeException e) {
        dashDate = ''; dashDateTo = ''; dateMode = 'custom'
        dateError = 'Enter a valid date range. Showing the last 6 months until a valid range is applied.'
    }
}
urlAll = '?dateMode=all' + _growthParam
urlToday = '?dateMode=today&dashDate=' + _todayStr + '&dashDateTo=' + _todayStr + _growthParam
urlWeek = '?dateMode=week&dashDate=' + _weekStart + '&dashDateTo=' + _todayStr + _growthParam
urlMonth = '?dateMode=month&dashDate=' + _monthStart + '&dashDateTo=' + _todayStr + _growthParam
url30 = '?dateMode=last30&dashDate=' + _today.minusDays(29) + '&dashDateTo=' + _todayStr + _growthParam
urlYear = '?dateMode=year&dashDate=' + _yearStart + '&dashDateTo=' + _todayStr + _growthParam
def _displayDate = java.time.format.DateTimeFormatter.ofPattern('d MMM yyyy', java.util.Locale.ENGLISH)
dashRangeLabel = dashDate ? (java.time.LocalDate.parse(dashDate).format(_displayDate) + (dashDateTo != dashDate ? ' – ' + java.time.LocalDate.parse(dashDateTo).format(_displayDate) : '')) : 'Last 6 Months'
presetActive = dashDate ? 'custom' : 'all'
if (dashDateTo == _todayStr) {
    def _presets = [today:_todayStr, week:_weekStart.toString(), month:_monthStart.toString(), last30:_today.minusDays(29).toString(), year:_yearStart.toString()]
    presetActive = _presets[dateMode] == dashDate ? dateMode : (_presets.find { it.value == dashDate }?.key ?: 'custom')
}
urlPrev = ''
if (dashDate) {
    def _first = java.time.LocalDate.parse(dashDate)
    def _last = java.time.LocalDate.parse(dashDateTo)
    def _prevEnd = _first.minusDays(1)
    def _prevStart = presetActive == 'week' ? _first.minusWeeks(1) : (presetActive == 'month' ? _first.minusMonths(1) : (presetActive == 'year' ? _first.minusYears(1) : _first.minusDays(java.time.temporal.ChronoUnit.DAYS.between(_first, _last) + 1L)))
    urlPrev = '?dateMode=custom&dashDate=' + _prevStart + '&dashDateTo=' + _prevEnd + _growthParam
}
showCustom = dateMode == 'custom' || presetActive == 'custom'
urlCustom = '?dateMode=custom&dashDate=' + dashDate + '&dashDateTo=' + dashDateTo + _growthParam
def _rangeParams = '?dateMode=' + presetActive + '&dashDate=' + dashDate + '&dashDateTo=' + dashDateTo
urlGrowthCurrent = _rangeParams + '&growthYear=' + _currentYear
urlGrowthPrevious = _rangeParams + '&growthYear=' + (_currentYear - 1)
growthPeriodLabel = growthYear == _currentYear ? 'This Year' : 'Last Year'
// window = selected range, else last 6 months
def _acStart; def _acEnd
if (dayStart) { _acStart = dayStart; _acEnd = dayEndExcl }
else {
    def _c6 = java.util.Calendar.getInstance(ec.user.timeZone); _c6.setTime(_now); _c6.set(java.util.Calendar.DAY_OF_MONTH,1); _c6.add(java.util.Calendar.MONTH,-5); _acStart = new java.sql.Timestamp(_c6.getTimeInMillis())
    def _ce2 = java.util.Calendar.getInstance(ec.user.timeZone); _ce2.setTime(_now); _ce2.add(java.util.Calendar.DAY_OF_MONTH,1); _acEnd = new java.sql.Timestamp(_ce2.getTimeInMillis())
}
def _daily = ((_acEnd.getTime() - _acStart.getTime()) / (1000L*60*60*24)) <= 62
def _bfmt = _daily ? new java.text.SimpleDateFormat("yyyy-MM-dd") : new java.text.SimpleDateFormat("yyyy-MM")
def _lfmt = _daily ? new java.text.SimpleDateFormat("dd MMM") : new java.text.SimpleDateFormat("MMM yy")

_bfmt.setTimeZone(ec.user.timeZone)
_lfmt.setTimeZone(ec.user.timeZone)

// one finalised-sales-invoice pass drives all range widgets
def _invs = orgId ? ef.find("mantle.account.invoice.Invoice")
                      .condition("fromPartyId", orgId)
                      .condition("invoiceTypeEnumId", "InvoiceSales")
                      .condition("statusId", EntityCondition.IN, ["InvoiceFinalized","InvoicePmtRecvd"])
                      .condition("invoiceDate", EntityCondition.GREATER_THAN_EQUAL_TO, _acStart)
                      .condition("invoiceDate", EntityCondition.LESS_THAN, _acEnd)
                      .selectField("toPartyId").selectField("invoiceDate")
                      .selectField("totalTaxableAmount").selectField("totalTaxAmount").selectField("roundOffAmount")
                      .list() : []

// build empty daily/monthly buckets across the window
def _keys = []; def _labelByKey = [:]; def _setBy = [:]
def _bc = java.util.Calendar.getInstance(ec.user.timeZone); _bc.setTime(_acStart); def _bendMs = _acEnd.getTime(); int _guard = 0
while (_bc.getTimeInMillis() < _bendMs && _guard < 400) {
    def _k = _bfmt.format(_bc.getTime())
    if (!_labelByKey.containsKey(_k)) { _keys.add(_k); _labelByKey[_k] = _lfmt.format(_bc.getTime()); _setBy[_k] = new HashSet() }
    _bc.add(_daily ? java.util.Calendar.DAY_OF_MONTH : java.util.Calendar.MONTH, 1); _guard++
}
def _custTotal = [:]; def _allCust = new HashSet()
_invs.each {
    if (!it.toPartyId) return
    def _k = _bfmt.format(it.invoiceDate)
    if (_setBy.containsKey(_k)) _setBy[_k].add(it.toPartyId)
    _allCust.add(it.toPartyId)
    def _amt = ((it.totalTaxableAmount ?: 0G) + (it.totalTaxAmount ?: 0G) + (it.roundOffAmount ?: 0G))
    _custTotal[it.toPartyId] = (_custTotal[it.toPartyId] ?: 0G) + _amt
}
def _aclbls=[]; def _acvals=[]
_keys.each { _k -> _aclbls.add(_labelByKey[_k]); _acvals.add(_setBy[_k].size()) }
acLabelsJson = groovy.json.JsonOutput.toJson(_aclbls)
acValsJson   = "["+_acvals.join(",")+"]"
acActiveInRange = _allCust.size()
acInvCount = _invs.size()
acHasData = _invs.size() > 0
acRangeLabel = dashDate ? (dashDate == dashDateTo ? dashDate : (dashDate + " to " + dashDateTo)) : "last 6 months"

// top customers by finalised sales value in the window
def _ct = _custTotal.entrySet().toList()
_ct.sort { a, b -> (b.value <=> a.value) }
def _topc = _ct.size() > 8 ? _ct.subList(0, 8) : _ct
def _tclbls=[]; def _tcvals=[]
for (e in _topc) {
    def _nm = null
    def _org = ef.find("mantle.party.Organization").condition("partyId", e.key).one()
    if (_org) _nm = _org.organizationName
    if (!_nm) { def _per = ef.find("mantle.party.Person").condition("partyId", e.key).one(); if (_per) _nm = ((_per.firstName ?: '') + ' ' + (_per.lastName ?: '')).trim() }
    if (!_nm) _nm = e.key
    _nm = _nm.toString()
    if (_nm.length() > 26) _nm = _nm.substring(0, 26)
    _tclbls.add(_nm)
    _tcvals.add(((e.value ?: 0G) as java.math.BigDecimal).setScale(0, java.math.RoundingMode.HALF_UP).toPlainString())
}
tcLabelsJson = groovy.json.JsonOutput.toJson(_tclbls)
tcValsJson   = "[" + _tcvals.join(",") + "]"
tcHasData    = (_tcvals.size() > 0)

// ===================== ZE-CONTACTS-DASH v2.1.0 (report-driven) — all REAL, org-scoped, MARUTHI-safe.
// Warehouses count, Total Contacts, all-time customer health, credit receivables + ageing + overdue
// bills, and the honest Business Health composite (never the mockup's fabricated numbers). =========
warehouseCount = orgId ? ef.find("mantle.facility.Facility").condition("ownerPartyId", orgId).condition("facilityTypeEnumId","FcTpWarehouse").count() : 0
def _allParties = new HashSet(); customerList.each { _allParties.add(it.partyId) }; vendorList.each { _allParties.add(it.partyId) }
totalContacts = _allParties.size()

// all-time finalised sales, per customer: last-purchase + lifetime value (drives active/at-risk/lost + high-value)
def _allInvs = orgId ? ef.find("mantle.account.invoice.Invoice").condition("fromPartyId", orgId).condition("invoiceTypeEnumId","InvoiceSales")
        .condition("statusId", EntityCondition.IN, ["InvoiceFinalized","InvoicePmtRecvd"])
        .selectField("toPartyId").selectField("invoiceDate").selectField("totalTaxableAmount").selectField("totalTaxAmount").selectField("roundOffAmount").list() : []
def _lastBy = [:]; def _totBy = [:]
def _nowMs = _now.getTime(); def _n90 = _nowMs - 90L*86400000L; def _n180 = _nowMs - 180L*86400000L; def _n30 = _nowMs - 30L*86400000L; def _n60 = _nowMs - 60L*86400000L
def _s30 = 0G; def _sp30 = 0G; def _s90 = 0G
_allInvs.each {
    def _amt = ((it.totalTaxableAmount ?: 0G) + (it.totalTaxAmount ?: 0G) + (it.roundOffAmount ?: 0G))
    def _d = it.invoiceDate ? it.invoiceDate.getTime() : 0L
    if (_d >= _n90) _s90 += _amt
    if (_d >= _n30) _s30 += _amt else if (_d >= _n60) _sp30 += _amt
    if (it.toPartyId) { if (_d > (_lastBy[it.toPartyId] ?: 0L)) _lastBy[it.toPartyId] = _d; _totBy[it.toPartyId] = (_totBy[it.toPartyId] ?: 0G) + _amt }
}
activeCust = 0; atRiskCust = 0; inactiveCust = 0
_lastBy.each { k, v -> if (v >= _n90) activeCust++ else if (v >= _n180) atRiskCust++ else inactiveCust++ }
lostCust = inactiveCust; goodStandingCust = activeCust
def _avgVal = _totBy ? (_totBy.values().sum() / _totBy.size()) : 0G
highValueCust = _totBy.values().count { it > _avgVal }

// credit receivables + ageing + top overdue bills (POS credit sales still outstanding)
totalReceivable = 0G; def _ageAmt = [0G,0G,0G,0G]; def _overdue = 0G; def _bills = []
try { if (orgId) ef.find("zenith.erp.pos.PosTransaction").condition("organizationPartyId", orgId).condition("isCredit","Y").condition("statusId","PtCompleted").list().each {
    def _out = ((it.payableAmount ?: 0G) as BigDecimal) - ((it.paidAmount ?: 0G) as BigDecimal)
    if (_out <= 0) return
    totalReceivable += _out
    def _days = it.entryDate ? (long)((_nowMs - it.entryDate.getTime())/86400000L) : 0L
    def _bi = _days<=30?0:(_days<=60?1:(_days<=90?2:3)); _ageAmt[_bi] += _out
    if (_days > 30) _overdue += _out
    _bills.add([out:_out, days:_days, cust:it.customerPartyId, no:it.transactionNumber])
} } catch (Exception e) {}
def _tt = totalReceivable > 0 ? totalReceivable.doubleValue() : 1.0
def _ageLbls = ['0 &ndash; 30 Days','31 &ndash; 60 Days','61 &ndash; 90 Days','90+ Days']; def _ageDot = ['#10B981','#F59E0B','#3B82F6','#EF4444']
ageRows = []
_ageLbls.eachWithIndex { lbl, i -> ageRows.add([label:lbl, amt:zinr.inr(ec.l10n.format(_ageAmt[i],'#,##,##0')), pct:(int)Math.round(_ageAmt[i].doubleValue()*100.0/_tt), dot:_ageDot[i]]) }
fmtReceivable = zinr.inr(ec.l10n.format(totalReceivable,'#,##,##0')); fmtOverdue = zinr.inr(ec.l10n.format(_overdue,'#,##,##0')); creditHasData = totalReceivable > 0
// Only bills older than the same 30-day threshold used by the overdue summary belong in this card.
_bills = _bills.findAll { it.days > 30 }
_bills.sort { a, b -> (b.out <=> a.out) }
overdueBills = []
_bills.take(5).each { bl ->
    def _nm = null
    if (bl.cust) { def _o=ef.find("mantle.party.Organization").condition("partyId",bl.cust).one(); if(_o)_nm=_o.organizationName
        if(!_nm){def _p=ef.find("mantle.party.Person").condition("partyId",bl.cust).one(); if(_p)_nm=((_p.firstName?:'')+' '+(_p.lastName?:'')).trim()} }
    if (!_nm || _nm.toString().trim()=='') _nm = 'Walk-in / Cash'
    def _pri = bl.out >= 50000 ? 'High' : (bl.out >= 20000 ? 'Medium' : 'Low')
    def _pc = (_pri=='High') ? ['#FEE2E2','#DC2626'] : ((_pri=='Medium') ? ['#FEF3C7','#D97706'] : ['#DBEAFE','#3B82F6'])
    overdueBills.add([name:_nm.toString(), no:(bl.no ?: ''), amt:zinr.inr(ec.l10n.format(bl.out,'#,##,##0')), days:bl.days, pri:_pri, pillBg:_pc[0], pillFg:_pc[1]])
}

// Business Health composite uses the existing five operational metrics.
healthMetrics = []; healthScore = 0; healthLabel = '—'; healthHasData = false; healthColor = '#9e9e9e'; healthBg = '#F3F4F6'
try {
    def _colr = { s -> s >= 80 ? 'good' : (s >= 55 ? 'warn' : 'bad') }
    def _pill = [good:['#ECFDF5','#059669'], warn:['#FFFBEB','#D97706'], bad:['#FEF2F2','#DC2626'], na:['#F3F4F6','#9CA3AF']]
    def _addm = { name, avail, score, status, ck -> def p=_pill[ck]?:_pill.na; healthMetrics.add([name:name, avail:avail, score:score, status:status, pillBg:p[0], pillFg:p[1]]) }
    if (_s30 <= 0 && _sp30 <= 0) { _addm('Sales', false, 0, 'No recent sales', 'na') }
    else { double _g = _sp30>0 ? ((_s30.doubleValue()-_sp30.doubleValue())*100.0/_sp30.doubleValue()) : (_s30>0?100.0:-100.0)
        def _sc=_g>=10?95:(_g>=0?80:(_g>=-15?60:35)); def _st=_g>=10?'Strong':(_g>=0?'Good':(_g>=-15?'Fair':'Weak')); def _gp=Math.round(_g)
        _addm('Sales', true, _sc, _st+' ('+(_gp>=0?'+':'')+_gp+'% vs prior 30d)', _colr(_sc)) }
    if (_s30 <= 0) { _addm('Cash Flow', false, 0, 'No recent sales', 'na') }
    else { def _outv=0G; try { ef.find("zenith.erp.pos.PosExpense").condition("organizationPartyId",orgId).condition("expenseDate",EntityCondition.GREATER_THAN_EQUAL_TO,new java.sql.Timestamp(_n30)).list().each{_outv+=((it.amount?:0G) as BigDecimal)} } catch(Exception e){}
        double _r=_outv.doubleValue()*100.0/_s30.doubleValue(); def _sc=_r<5?95:(_r<15?80:(_r<30?60:35)); def _st=_r<5?'Strong':(_r<15?'Healthy':(_r<30?'Watch':'Tight')); _addm('Cash Flow', true, _sc, _st, _colr(_sc)) }
    if (!orgId) { _addm('Receivables', false, 0, 'No organization selected', 'na') }
    else if (totalReceivable <= 0) { _addm('Receivables', true, 100, 'Nothing outstanding', 'good') }
    else { double _r=_s90>0?(totalReceivable.doubleValue()/_s90.doubleValue()):1.0; def _sc=_r<0.02?95:(_r<0.10?80:(_r<0.25?55:30)); def _st=_r<0.02?'Healthy':(_r<0.10?'OK':(_r<0.25?'Needs Attention':'High')); _addm('Receivables', true, _sc, _st, _colr(_sc)) }
    def _prodTot = orgId ? ef.find("mantle.product.Product").condition("ownerPartyId",orgId).count() : 0
    if (_prodTot > 0) {
        def _tracked = ef.find("mantle.product.Product").condition("ownerPartyId",orgId).condition("inventoryTracked","Y").count()
        if (_tracked >= 5) { def _low=0; try { ef.find("zenith.erp.inventory.ProductStockView").condition("ownerPartyId",orgId).list().each{ def q=((it.totalQoh?:0G) as BigDecimal); def rp=((it.reorderPoint?:0G) as BigDecimal); if(q<=0||(rp>0&&q<=rp)) _low++ } } catch(Exception e){}
            double _r=_low*1.0/_tracked; def _sc=_r<0.05?95:(_r<0.15?80:(_r<0.30?55:30)); def _st=_r<0.05?'Healthy':(_r<0.15?'Good':(_r<0.30?'Needs Attention':'Low')); _addm('Inventory', true, _sc, _st, _colr(_sc)) }
        else { def _wp=ef.find("mantle.product.Product").condition("ownerPartyId",orgId).condition("mrpAmount",EntityCondition.GREATER_THAN,0G).count(); double _r=_wp*1.0/_prodTot; def _sc=_r>=0.95?90:(_r>=0.80?75:(_r>=0.50?55:35)); def _st=_r>=0.80?'Catalog ready':(_r>=0.50?'Some unpriced':'Many unpriced'); _addm('Inventory', true, _sc, _st, _colr(_sc)) }
        def _cf=ec.entity.conditionFactory; def _gc=_cf.makeCondition([_cf.makeCondition("gstSlabId",EntityCondition.IS_NOT_NULL,null),_cf.makeCondition("isGstExempt",EntityCondition.EQUALS,"Y"),_cf.makeCondition("hsnCode",EntityCondition.IS_NOT_NULL,null)],EntityCondition.OR)
        def _go=ef.find("mantle.product.Product").condition("ownerPartyId",orgId).condition(_gc).count(); double _r=_go*1.0/_prodTot; def _sc=_r>=0.95?95:(_r>=0.80?80:(_r>=0.50?55:30)); def _st=_r>=0.95?'Compliant':(_r>=0.80?'Mostly set':(_r>=0.50?'Partial':'Needs setup')); _addm('GST', true, _sc, _st, _colr(_sc))
    }
    if (_prodTot == 0) { _addm('Inventory', false, 0, 'No products yet', 'na'); _addm('GST', false, 0, 'No products yet', 'na') }
    def _av = healthMetrics.findAll { it.avail }; healthHasData = (_av.size() > 0)
    healthScore = healthHasData ? (int) Math.round(_av.sum { it.score } / _av.size()) : 0
    healthLabel = healthScore>=85?'Excellent':(healthScore>=70?'Good':(healthScore>=55?'Fair':'Needs Work'))
    healthColor = healthScore>=70?'#059669':(healthScore>=55?'#D97706':'#DC2626')
    healthBg = healthScore>=70?'#ECFDF5':(healthScore>=55?'#FFFBEB':'#FEF2F2')
} catch (Exception e) { healthMetrics=[]; healthScore=0; healthLabel='—'; healthHasData=false; healthColor='#9e9e9e'; healthBg='#F3F4F6' }

// ---- Contact Map: customers plotted on an inline SVG India map (server-rendered → works on /apps AND /qapps).
// Aggregate by city (fallback state) from the address on file; equirectangular projection to the viewBox. ----
def _cc = [bhavani:[11.45,77.68],erode:[11.34,77.72],coimbatore:[11.02,76.96],salem:[11.66,78.15],tiruppur:[11.11,77.34],tirupur:[11.11,77.34],karur:[10.96,78.08],namakkal:[11.22,78.17],dindigul:[10.36,77.98],chennai:[13.08,80.27],madurai:[9.93,78.12],trichy:[10.79,78.70],tiruchirappalli:[10.79,78.70],thanjavur:[10.79,79.14],vellore:[12.92,79.13],tirunelveli:[8.71,77.76],pondicherry:[11.94,79.83],puducherry:[11.94,79.83],bangalore:[12.97,77.59],bengaluru:[12.97,77.59],mysore:[12.30,76.64],mangalore:[12.91,74.86],hyderabad:[17.38,78.49],mumbai:[19.08,72.88],delhi:[28.61,77.21],kolkata:[22.57,88.36],pune:[18.52,73.86],ahmedabad:[23.03,72.58],jaipur:[26.91,75.79],kochi:[9.93,76.27],cochin:[9.93,76.27],trivandrum:[8.52,76.94],thiruvananthapuram:[8.52,76.94],vijayawada:[16.51,80.65],visakhapatnam:[17.69,83.22],nagpur:[21.15,79.09],lucknow:[26.85,80.95],surat:[21.17,72.83],vadodara:[22.31,73.19],indore:[22.72,75.86],bhopal:[23.26,77.41],patna:[25.59,85.14],guwahati:[26.14,91.74],bhubaneswar:[20.30,85.82],chandigarh:[30.73,76.78],ludhiana:[30.90,75.86],rajkot:[22.30,70.80],nashik:[19.99,73.78],goa:[15.30,74.12]]
def _sc = ['IND_TN':[10.9,78.3],'IND_KA':[14.5,76.0],'IND_KL':[10.3,76.5],'IND_AP':[15.5,79.5],'IND_TG':[17.9,79.0],'IND_MH':[19.4,76.5],'IND_GJ':[22.7,71.8],'IND_RJ':[26.8,73.8],'IND_UP':[27.0,80.5],'IND_MP':[23.7,78.5],'IND_WB':[23.5,87.8],'IND_DL':[28.6,77.2],'IND_PB':[31.0,75.4],'IND_HR':[29.2,76.3],'IND_BR':[25.7,85.5],'IND_OD':[20.7,85.0],'IND_OR':[20.7,85.0],'IND_JH':[23.6,85.3],'IND_CG':[21.3,82.0],'IND_AS':[26.3,92.8],'IND_UT':[30.0,79.2],'IND_HP':[31.8,77.3],'IND_GA':[15.4,74.0]]
def _px = { lng -> (int)Math.round((((lng as double) - 67.0) / 31.0) * 448.0 + 16.0) }
def _py = { lat -> (int)Math.round(((37.5 - (lat as double)) / 31.5) * 288.0 + 16.0) }
