def _gmf = new java.text.SimpleDateFormat("yyyy-MM"); def _gml = new java.text.SimpleDateFormat("MMM yy")
def _newBy = [:]; _acq.each { pid, dt -> def _k = _gmf.format(dt); _newBy[_k] = (_newBy[_k] ?: 0) + 1 }
growthHasData = (_acq.size() > 0); growthTotal = _acq.size(); growthDots = []; growthXLabels = []; growthLine = ''; growthArea = ''; growthTicks = []; growthEnd = null
if (growthHasData) {
    def _cur = growthYear == _currentYear ? _gmf.format(_now) : growthYear + '-12'; def _startKey = growthYear + '-01'
    def _before = 0; _acq.each { pid, dt -> if (_gmf.format(dt) < _startKey) _before++ }
    def _mkeys = []; def _mlabels = []
    def _it = java.util.Calendar.getInstance(); _it.setTime(_gmf.parse(_startKey))
    def _endC = java.util.Calendar.getInstance(); _endC.setTime(_gmf.parse(_cur)); int _g2 = 0
    while (!_it.getTime().after(_endC.getTime()) && _g2 < 24) { _mkeys.add(_gmf.format(_it.getTime())); _mlabels.add(_gml.format(_it.getTime())); _it.add(java.util.Calendar.MONTH,1); _g2++ }
    def _newArr = _mkeys.collect { _newBy[it] ?: 0 }
    def _cumArr = []; def _run = _before; _newArr.each { _run += it; _cumArr.add(_run) }
    def _cMax = Math.max(4, (int)(Math.ceil((_cumArr.max() ?: 0) / 4.0) * 4))
    double _x0=55, _x1=570, _yb=220, _yt=20; int _n=_mkeys.size(); double _slot=(_x1-_x0)/_n
    def _lb = new StringBuilder()
    for (int i=0;i<_n;i++) {
        double _cx = _x0 + _slot*i + _slot/2
        double _cy = _yb - (_cumArr[i]/(double)_cMax)*(_yb-_yt)
        _lb.append((i==0?'':' ') + ((int)Math.round(_cx)) + ',' + ((int)Math.round(_cy)))
        growthDots.add([cx:(int)Math.round(_cx), cy:(int)Math.round(_cy), n:_cumArr[i]])
        growthXLabels.add([x:(int)Math.round(_cx), t:_mlabels[i]])
    }
    growthLine = _lb.toString()
    growthArea = growthLine + ' ' + growthDots[-1].cx + ',220 ' + growthDots[0].cx + ',220'
    growthEnd = growthDots[-1]
    growthTotal = growthEnd.n
    [0,1,2,3,4].each { i -> growthTicks.add([y:20+i*50, label:(int)Math.round(_cMax*(4-i)/4.0)]) }
}

